// OPTIMIZED: Batch query before loop
// Original: 5 async call(s) inside loop over envelope.envelopeItems
// Problem: N+1 queries where N = envelope.envelopeItems.length

// Step 1: Collect all IDs/keys needed
const allIds = envelope.envelopeItems.map(item => item.id);

// Step 2: Batch query (single database call)
const allData = await batchQuery(allIds); // Replace with actual batch query
const dataMap = new Map(allData.map(d => [d.id, d]));

// Step 3: Original loop (now uses cached data)
for (const item of envelope.envelopeItems) {
    const existingFields = await prisma.field.findMany({
      where: {
        envelopeItemId: item.id,
      },
    });

    const pdfBytes = await getFileServerSide(item.documentData);
    const fields = await detectFieldsFromPdf({
      pdfBytes,
      existingFields,
      recipients,
      context,
      onProgress,
    });

    // Resolve recipientKey to actual recipient and add context
    const fieldsWithContext = dataMap.get(item.id) => {
        const { recipientKey, ...fieldWithoutKey } = field;

        let resolvedRecipient = resolveRecipientFromKey(recipientKey, recipients);

        // If no recipients exist, create a blank recipient
        if (!resolvedRecipient) {
          const { recipients: createdRecipients } = await createEnvelopeRecipients({
            id: {
              id: envelope.id,
              type: 'envelopeId',
            },
            recipients: [
              {
                name: '',
                email: '',
                role: RecipientRole.SIGNER,
              },
            ],
            userId,
            teamId,
          });

          resolvedRecipient = createdRecipients[0];
        }

        return {
          ...fieldWithoutKey,
          envelopeItemId: item.id,
          recipientId: resolvedRecipient.id,
        };
      }),
    );

    allFields.push(...fieldsWithContext);
  }

// Performance: 1 query instead of N queries

// OPTIMIZED: Prisma eager loading with include
// Original: Separate queries for field and field
// Optimized: Single query with include

const fieldWithRelations = await prisma.field.findMany({
  include: {
    field: true, // Eager load field
  }
});

